+      return "tiles (count " + std::to_string(ifd.getEntry(Tag::TileOffsets).count()) + ")";
+    }
+    if (ifd.entries().contains(Tag::StripOffsets)) {
+      return "strips (count " + std::to_string(ifd.getEntry(Tag::StripOffsets).count()) + ")";
+    }
+    return "n/a";
+  }
+
