+        std::cout << "  Total image data bytes: " << totalBytesString(ifd) << "\n";
+      }
+    }
+  }
+  catch (const std::exception& ex) {
+    std::cerr << "Error: " << ex.what() << "\n";
+    return 1;
+  }
